<?php
declare(strict_types=1);
function ownerUnlimitedCases(array &$tests,ControlCenter\Application $app,ControlCenter\Config $config,array $owner,array $reseller):void {
    $tests['owner-only unlimited trials preserve history and eligibility while removing only the daily and pilot ceilings']=function()use($app,$config,$owner,$reseller):void {
        $brand=$app->db->one("SELECT b.* FROM app_brands b JOIN tenants t ON t.id=b.tenant_id WHERE t.kind='owner'");check($brand!==null);$tenant=$brand['tenant_id'];
        if(!$app->db->one('SELECT panel_id FROM panel_resellers WHERE tenant_id=?',[$tenant]))$app->db->query('INSERT INTO panel_resellers (panel_id,tenant_id,username,linked_by) VALUES (?,?,?,?)',['88000001',$tenant,'TEST-owner-panel',$owner['id']]);
        $values=array_replace($config->values,['trial_worker'=>['shared_secret'=>str_repeat('3',64)],'trial_public_signup_enabled'=>true,'trial_channel'=>'testing','trial_reseller_daily_limit'=>1,'trial_pilot_brand_id'=>$brand['id'],'trial_owner_unlimited_brand_id'=>$brand['id'],'trial_device_daily_limit'=>1,'trial_ip_hourly_limit'=>2]);
        $c=new ControlCenter\Config($config->root,$values);$secrets=new ControlCenter\Secrets($c);$calls=0;
        $worker=new ControlCenter\TrialWorker($c,function($path,$body)use(&$calls):string {$s=json_decode($body,true);same('/branded-trials/provision',$path);$calls++;return json_encode(['state'=>'prepared','operation_id'=>$s['operation_id'],'reseller_id'=>$s['reseller_id'],'line_id'=>(string)(990000+$calls),'plan_id'=>$s['package_id'],'plan_fingerprint'=>$s['plan_fingerprint'],'notes_recorded'=>true,'account'=>['username'=>'SYNTHETIC','password'=>'SYNTHETIC','activation_code'=>'123456','exp_date'=>time()+86400]]);});
        $policies=new ControlCenter\TrialPolicies($app->db,$app->management,$app->auth,$worker);$artifacts=new ControlCenter\BrandArtifacts($app->db,$secrets,$c);$offers=new ControlCenter\TrialOffers($app->db,$c,$app->management,$app->auth,$secrets,$policies,$artifacts);
        // Synthetic local fixture registration only; no signing/panel/network call.
        $id=ControlCenter\Database::id();$manifest=['app_version'=>'2.0.118','app_version_code'=>434];$app->db->query('INSERT INTO app_brand_builds (id,brand_id,brand_version,app_version,manifest,requested_by,build_channel) VALUES (?,?,?,?,?,?,?)',[$id,$brand['id'],$brand['version'],'2.0.118',json_encode($manifest),$owner['id'],'testing']);
        $artifacts->recordVerified($id,['channel'=>'testing','package_name'=>$brand['package_name'].'.test','version_name'=>'2.0.118.'.$brand['version'].'-test','version_code'=>43400000+(int)$brand['version'],'trial_protocol'=>1,'signer_sha256'=>'3273d0b0294a689565ab4b0c8ef7e1887e2ca680240718f5521628b5c46328b7','apk_sha256'=>str_repeat('a',64),'artifact_url'=>'https://github.com/derangedchief-crypto/ARVIO/releases/download/brand-'.$brand['id'].'-testing/Brand-synthetic.apk']);
        $global=$offers->globalSettings($owner);if(!$global['enabled'])$offers->setGlobal($owner,['enabled'=>true,'expected_revision'=>$global['revision']]);
        $history=$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id');$contacts=$app->db->all('SELECT * FROM trial_contacts ORDER BY id');$state=$offers->managerState($owner,[]);same(true,$state['owner_unlimited']);same(null,$state['daily_cap']);same(null,$state['pilot']);
        problem(404,fn()=> $offers->publish($reseller,['tenant_id'=>$tenant,'enabled'=>true,'confirmed_public_mode'=>true]));
        $offers->publish($owner,['enabled'=>true,'confirmed_public_mode'=>true,'expected_revision'=>(int)($state['publication']['revision']??0)]);$offer=$offers->admitted($brand['id']);same(0,$offer['daily_limit']);same(true,$offer['owner_unlimited']);same($history,$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id'));same($contacts,$app->db->all('SELECT * FROM trial_contacts ORDER BY id'));same(0,$calls);
        $sessions=new ControlCenter\TrialPublicSessions($app->db,$offers,$secrets,$app->auth);$broker=new ControlCenter\TrialSignupBroker($app->db,$c,$secrets,$app->auth,$offers,$sessions,new ControlCenter\TrialBudgets($app->db,$c),$worker,new ControlCenter\TrialContacts($app->db,$app->management,$app->auth,$secrets,$c,$worker));
        $make=function(string $phone,string $device)use($sessions,$offers,$brand):array {$key=openssl_pkey_new(['private_key_type'=>OPENSSL_KEYTYPE_EC,'curve_name'=>'prime256v1']);$pem=openssl_pkey_get_details($key)['key'];$der=base64_decode(preg_replace('~-----[^\n]+-----|\s~','',$pem));$contact=['first_name'=>'TEST Owner prospect','phone'=>$phone];$hash=ControlCenter\TrialPublicSessions::requestHash($contact);$s=$sessions->create(['brand_id'=>$brand['id'],'offer_revision'=>$offers->publicInfo($brand['id'])['offer_revision'],'device_claim'=>$device,'public_key'=>base64_encode($der),'request_hash'=>$hash],'127.0.0.249');openssl_sign($s['signing_text'],$signature,$key,OPENSSL_ALGO_SHA256);return ['token'=>$s['token'],'nonce'=>$s['nonce'],'signature'=>base64_encode($signature),'request_hash'=>$hash,'first_name'=>$contact['first_name'],'phone'=>$phone,'notice_accepted'=>true];};
        $first=$make('+15550000901',str_repeat('1',64));same('prepared',$broker->submit($first)['state']);$second=$make('+15550000902',str_repeat('2',64));same('prepared',$broker->submit($second)['state']);same(2,$calls);same('prepared',$broker->submit($first)['state']);same(2,$calls);
        problem(409,fn()=> $broker->submit($make('+15550000901',str_repeat('1',64))));same(2,$calls);
        problem(429,fn()=> $broker->submit($make('+15550000903',str_repeat('1',64))));problem(429,fn()=> $broker->submit($make('+15550000904',str_repeat('4',64))));same(2,$calls);
        $global=$offers->globalSettings($owner);$offers->setGlobal($owner,['enabled'=>false,'expected_revision'=>$global['revision']]);same(false,$offers->publicInfo($brand['id'])['available']);
        $state=$offers->managerState($owner,[]);$offers->publish($owner,['expected_revision'=>(int)$state['publication']['revision'],'enabled'=>false]);same('123456',$broker->status($first)['activation_code']);same(2,$calls);
        // A private configuration pointing at a reseller still cannot grant owner status.
        $sellerBrand=$app->db->one('SELECT id FROM app_brands WHERE tenant_id=?',[$reseller['tenant_id']]);$wrong=new ControlCenter\Config($config->root,array_replace($values,['trial_owner_unlimited_brand_id'=>$sellerBrand['id']]));$wrongOffers=new ControlCenter\TrialOffers($app->db,$wrong,$app->management,$app->auth,$secrets,$policies,$artifacts);same(false,$wrongOffers->managerState($reseller,[])['owner_unlimited']);same(1,$wrongOffers->managerState($reseller,[])['daily_cap']);
        $finiteValues=$values;unset($finiteValues['trial_owner_unlimited_brand_id']);$finiteConfig=new ControlCenter\Config($config->root,$finiteValues);$finite=new ControlCenter\TrialOffers($app->db,$finiteConfig,$app->management,$app->auth,$secrets,$policies,$artifacts);$revision=(int)$finite->managerState($owner,[])['publication']['revision'];
        foreach([0,2,'1',1.5] as $bad){try{$finite->publish($owner,['expected_revision'=>$revision,'enabled'=>true,'confirmed_public_mode'=>true,'daily_limit'=>$bad]);throw new RuntimeException('Expected daily limit rejection');}catch(ControlCenter\Problem $e){same(422,$e->status);same('Choose a whole-number daily trial limit from 1 to 1.',$e->getMessage());}}
        same(2,$calls);
    };
    $tests['publication validation identifies bad revision separately from bad daily limits']=function()use($app,$config,$owner,$reseller):void {
        $c=new ControlCenter\Config($config->root,array_replace($config->values,['trial_worker'=>['shared_secret'=>str_repeat('d',64)],'trial_public_signup_enabled'=>true,'trial_channel'=>'testing','trial_reseller_daily_limit'=>1]));$s=new ControlCenter\Secrets($c);$worker=new ControlCenter\TrialWorker($c);$offers=new ControlCenter\TrialOffers($app->db,$c,$app->management,$app->auth,$s,new ControlCenter\TrialPolicies($app->db,$app->management,$app->auth,$worker),new ControlCenter\BrandArtifacts($app->db,$s,$c));
        foreach(['3',1.5] as $revision){try{$offers->publish($reseller,['expected_revision'=>$revision,'enabled'=>true,'confirmed_public_mode'=>true,'daily_limit'=>1]);throw new RuntimeException('Expected revision rejection');}catch(ControlCenter\Problem $e){same(422,$e->status);check(str_contains($e->getMessage(),'offer revision'));}}
    };
}
